// 从频道链接中提取频道标识
const channelLink = $json['频道链接'] || '';
let identifier = '';
let idType = '';

if (channelLink.includes('@')) {
  // 提取 @handle 名，如 https://www.youtube.com/@MrBeast → MrBeast
  const match = channelLink.match(/@([\w.-]+)/);
  if (match) {
    identifier = match[1];
    idType = 'handle';
  }
} else if (channelLink.includes('/channel/')) {
  // 提取 channel ID，如 https://www.youtube.com/channel/UCX6OQ3DkcsbYNE6H8uQQuVA
  const match = channelLink.match(/\/channel\/([\w-]+)/);
  if (match) {
    identifier = match[1];
    idType = 'channelId';
  }
} else if (channelLink.includes('/c/')) {
  // 提取自定义名称
  const match = channelLink.match(/\/c\/([\w.-]+)/);
  if (match) {
    identifier = match[1];
    idType = 'custom';
  }
} else {
  // 尝试从URL路径提取
  const match = channelLink.match(/youtube\.com\/([\w.-]+)/);
  if (match && match[1] !== 'watch' && match[1] !== 'playlist') {
    identifier = match[1];
    idType = 'handle';
  }
}

const channelName = $json['频道名称'] || '';

return [{
  json: {
    identifier: identifier,
    idType: idType,
    channelName: channelName,
    channelLink: channelLink
  }
}];

// 统一处理：从两种路径获取 channelId 和 uploads playlistId
const items = $input.first().json.items || [];
let channelId = '';

if (items.length > 0) {
  // contentDetails 直接返回的结构
  if (items[0].id) {
    channelId = items[0].id;
  } else if (items[0].snippet && items[0].snippet.channelId) {
    // search 返回的结构
    channelId = items[0].snippet.channelId;
  }
}

// 获取之前的上下文
const prevData = $('提取频道标识').item.json;
const channelName = prevData.channelName || '';

if (!channelId) {
  return [{ json: { channelId: '', uploadsPlaylistId: '', channelName: channelName, error: '未找到频道ID' } }];
}

return [{
  json: {
    channelId: channelId,
    channelName: channelName
  }
}];

// 提取 uploads playlistId，初始化分页状态
const items = $input.first().json.items || [];
const channelName = $('统一频道ID').item.json.channelName || '';

let uploadsPlaylistId = '';
if (items.length > 0 && items[0].contentDetails && items[0].contentDetails.relatedPlaylists) {
  uploadsPlaylistId = items[0].contentDetails.relatedPlaylists.uploads || '';
}

if (!uploadsPlaylistId) {
  return [{ json: { error: '未找到上传播放列表', allVideoIds: [], channelName: channelName } }];
}

return [{
  json: {
    playlistId: uploadsPlaylistId,
    pageToken: '',
    collectedVideoIds: [],
    channelName: channelName
  }
}];

// 获取视频列表（支持分页循环，最多100条）
const apiKey = 'YOUR_YOUTUBE_API_KEY';
const data = $input.first().json;
const playlistId = data.playlistId;
const existingIds = data.collectedVideoIds || [];
const pageToken = data.pageToken || '';
const channelName = data.channelName || '';

// 构建URL
let url = `https://www.googleapis.com/youtube/v3/playlistItems?part=snippet&maxResults=50&playlistId=${playlistId}&key=${apiKey}`;
if (pageToken) {
  url += `&pageToken=${pageToken}`;
}

// 使用 fetch 获取数据（n8n Code 节点支持 fetch）
const response = await fetch(url);
const result = await response.json();

// 收集本页视频ID
const newIds = (result.items || [])
  .map(item => item.snippet?.resourceId?.videoId)
  .filter(id => id);

const allIds = [...existingIds, ...newIds];
const nextPageToken = result.nextPageToken || '';
const totalResults = result.pageInfo?.totalResults || 0;

// 判断是否继续：有下一页 且 已收集不足100条
const hasMore = nextPageToken && allIds.length < 100;

return [{
  json: {
    playlistId: playlistId,
    pageToken: hasMore ? nextPageToken : '',
    collectedVideoIds: allIds,
    hasMore: hasMore,
    channelName: channelName
  }
}];

// 批量获取视频详情（每批最多50个）
const apiKey = 'YOUR_YOUTUBE_API_KEY';
const data = $input.first().json;
const videoIds = data.collectedVideoIds || [];
const channelName = data.channelName || '';

if (videoIds.length === 0) {
  return [{ json: { videos: [], channelName: channelName } }];
}

// 分批请求（每批最多50个ID）
const allVideos = [];
for (let i = 0; i < videoIds.length; i += 50) {
  const batch = videoIds.slice(i, i + 50);
  const url = `https://www.googleapis.com/youtube/v3/videos?part=snippet,statistics&id=${batch.join(',')}&key=${apiKey}`;

  const response = await fetch(url);
  const result = await response.json();

  for (const video of (result.items || [])) {
    allVideos.push({
      频道名: channelName,
      视频标题: video.snippet?.title || '',
      播放量: parseInt(video.statistics?.viewCount || '0'),
      发布时间: video.snippet?.publishedAt || '',
      视频链接: `https://youtube.com/watch?v=${video.id}`,
      点赞数: parseInt(video.statistics?.likeCount || '0'),
      评论数: parseInt(video.statistics?.commentCount || '0')
    });
  }
}

return allVideos.map(v => ({ json: v }));

// 汇总所有频道的视频数据，按播放量降序排序
const allVideos = $input.all().map(item => item.json);

// 按播放量降序排列
allVideos.sort((a, b) => (b.播放量 || 0) - (a.播放量 || 0));

return allVideos.map(video => ({ json: video }));
